export interface Reply { uri: string; }
export type Upload = (ownerId: string) => Promise<Reply>;
export class UploadSession {
  ownerId: string = '';
  resultUri: string = '';
  setOwner(ownerId: string): void { this.ownerId = ownerId; this.resultUri = ''; }
  async send(upload: Upload): Promise<void> {
    const reply = await upload(this.ownerId);
    this.resultUri = reply.uri;
  }
}

