export type Load = (id: string) => Promise<string>;
export class NotebookSession {
  notebookId: string = '';
  text: string = '';
  open(id: string): void { this.notebookId = id; this.text = ''; }
  async refresh(load: Load): Promise<void> {
    const value = await load(this.notebookId);
    this.text = value;
  }
}
